changeSet.sql:
ALTER TABLE campo_ficha ADD CONSTRAINT ck_campo_ficha_pontos
CHECK (pontos IS NULL
       OR (tipo = 'OPCOES' AND opcoes IS NOT NULL AND grupo_escore IS NOT NULL));

ALTER TABLE ficha_anamnese ADD CONSTRAINT ck_ficha_anamnese_escore_tom
CHECK (escore_tom IS NULL
       OR escore_tom IN ('NEUTRO', 'ADEQUADO', 'ATENCAO', 'CRITICO'));
